questions.solution:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <semaphore.h>

#define N 10

int buf[N];
int head = 0, tail = 0;
int P, C, K;
long consumed = 0;
sem_t spaces, items, mutex, count_lock;

void put(int x) {
    sem_wait(&spaces);             /* counting semaphore first ... */
    sem_wait(&mutex);              /* ... then the buffer lock      */
    buf[tail] = x;
    tail = (tail + 1) % N;
    sem_post(&mutex);
    sem_post(&items);
}

int get(void) {
    sem_wait(&items);
    sem_wait(&mutex);
    int x = buf[head];
    head = (head + 1) % N;
    sem_post(&mutex);
    sem_post(&spaces);
    return x;
}

void *producer(void *arg) {
    int p = (int)(intptr_t)arg;
    for (int j = 0; j < K; j++) put(p * 1000 + j);
    return NULL;
}

void *consumer(void *arg) {
    for (;;) {
        int x = get();
        if (x == -1) break;        /* sentinel: this consumer is done */
        sem_wait(&count_lock);
        consumed++;
        sem_post(&count_lock);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 4) { fprintf(stderr, "Usage: %s P C K\n", argv[0]); return 1; }
    P = atoi(argv[1]); C = atoi(argv[2]); K = atoi(argv[3]);
    sem_init(&spaces, 0, N);
    sem_init(&items, 0, 0);
    sem_init(&mutex, 0, 1);
    sem_init(&count_lock, 0, 1);

    pthread_t *pt = malloc(P * sizeof *pt), *ct = malloc(C * sizeof *ct);
    for (int i = 0; i < C; i++) pthread_create(&ct[i], NULL, consumer, NULL);
    for (int i = 0; i < P; i++) pthread_create(&pt[i], NULL, producer, (void *)(intptr_t)i);

    for (int i = 0; i < P; i++) pthread_join(pt[i], NULL);
    for (int i = 0; i < C; i++) put(-1);          /* one sentinel per consumer */
    for (int i = 0; i < C; i++) pthread_join(ct[i], NULL);

    long produced = (long)P * K;
    printf("produced=%ld consumed=%ld %s\n", produced, consumed,
           produced == consumed ? "MATCH" : "MISMATCH");

    sem_destroy(&spaces); sem_destroy(&items); sem_destroy(&mutex); sem_destroy(&count_lock);
    free(pt); free(ct);
    return 0;
}
